"""Streaming response adapter — turns the SDK's ``ChatCompletionChunk`` async
iterator into PydanticAI ``ModelResponseStreamEvent`` objects."""

from __future__ import annotations

from collections.abc import AsyncIterator
from datetime import datetime, timezone

from gigachat.models import ChatCompletionChunk, Usage
from pydantic_ai.messages import ModelResponseStreamEvent
from pydantic_ai.models import ModelRequestParameters, StreamedResponse
from pydantic_ai.usage import RequestUsage

from pydantic_ai_gigachat._mappers import map_finish_reason, usage_from_gigachat


class GigaChatStreamedResponse(StreamedResponse):
    """Consumes ``GigaChat.astream`` chunks and yields pydantic_ai stream events."""

    def __init__(
        self,
        *,
        model_name: str,
        provider_name: str,
        provider_url: str,
        chunk_iterator: AsyncIterator[ChatCompletionChunk],
        model_request_parameters: ModelRequestParameters,
    ) -> None:
        super().__init__(model_request_parameters)
        self._model_name = model_name
        self._provider_name = provider_name
        self._provider_url = provider_url
        self._chunk_iterator = chunk_iterator
        self._timestamp = datetime.now(tz=timezone.utc)

    @property
    def model_name(self) -> str:
        return self._model_name

    @property
    def provider_name(self) -> str:
        return self._provider_name

    @property
    def provider_url(self) -> str:
        return self._provider_url

    @property
    def timestamp(self) -> datetime:
        return self._timestamp

    async def _get_event_iterator(self) -> AsyncIterator[ModelResponseStreamEvent]:
        text_part_id = "text-0"
        tool_part_id = "tool-0"

        async for chunk in self._chunk_iterator:
            for event in self._handle_chunk(chunk, text_part_id, tool_part_id):
                yield event

    def _handle_chunk(
        self,
        chunk: ChatCompletionChunk,
        text_part_id: str,
        tool_part_id: str,
    ) -> list[ModelResponseStreamEvent]:
        events: list[ModelResponseStreamEvent] = []
        if not chunk.choices:
            self._update_usage(chunk.usage)
            return events

        choice = chunk.choices[0]
        delta = choice.delta

        if delta.content:
            for ev in self._parts_manager.handle_text_delta(
                vendor_part_id=text_part_id,
                content=delta.content,
            ):
                events.append(ev)

        fn_call = delta.function_call
        if fn_call is not None:
            tool_event = self._parts_manager.handle_tool_call_delta(
                vendor_part_id=tool_part_id,
                tool_name=fn_call.name,
                args=fn_call.arguments,
            )
            if tool_event is not None:
                events.append(tool_event)

        mapped_finish = map_finish_reason(choice.finish_reason)
        if mapped_finish is not None:
            self._finish_reason = mapped_finish

        self._update_usage(chunk.usage)
        return events

    def _update_usage(self, usage_payload: Usage | None) -> None:
        if usage_payload is None:
            return
        counts = usage_from_gigachat(usage_payload)
        # GigaChat sends cumulative totals on each chunk that carries usage,
        # so overwrite rather than accumulate.
        self._usage = RequestUsage(
            input_tokens=counts["input_tokens"],
            output_tokens=counts["output_tokens"],
            cache_read_tokens=counts["cache_read_tokens"],
        )
